S = "Hakeem Force Academy"
QS = [
(S, "What is the capital of Iceland?", ["Oslo", "Reykjavik", "Helsinki", "Copenhagen"], 1, "Reykjavik is the capital and largest city of Iceland. It is the northernmost capital of a sovereign state.", "Iceland is a Nordic island country in the North Atlantic Ocean.", [209]),
(S, "What was the relationship between Hazrat Ishaq (AS) and Hazrat Ibrahim (AS)?", ["Son", "Brother", "Nephew", "Grandson"], 0, "Hazrat Ishaq (AS) was the son of Hazrat Ibrahim (AS) and Hazrat Sarah (AS). He was the younger brother of Hazrat Ismail (AS).", "Hazrat Yaqub (AS) was the son of Hazrat Ishaq (AS).", [3687]),
(S, "Find the value of i(-2i + 3), where i is the imaginary unit.", ["-2 + 3i", "2 + 3i", "2 - 3i", "-2 - 3i"], 1, "Multiply out: i(-2i + 3) = -2i squared + 3i. Since i squared = -1, this is 2 + 3i.", "The imaginary unit i is defined by i squared = -1.", [1665]),
(S, "What are the real and imaginary parts of the complex number 4 + 9i?", ["Real part 9, imaginary part 4", "Real part 4, imaginary part 9", "Real part 4, imaginary part 9i", "Real part 13, imaginary part 0"], 1, "In a + bi, a is the real part and b is the imaginary part. So the real part is 4 and the imaginary part is 9.", "The imaginary part is the real coefficient b, not bi.", [836]),
(S, "What is the imaginary part of the complex number 3 + 9i?", ["3", "12", "9", "27"], 2, "In the form a + bi the imaginary part is b. Here b = 9.", "The real part of 3 + 9i is 3.", [3429]),
(S, "What is the imaginary part of the number -(2i + 3)?", ["2", "-2", "-3", "3"], 1, "-(2i + 3) = -3 - 2i. The coefficient of i is -2, so the imaginary part is -2.", "The real part of -(2i + 3) is -3.", [3428]),
(S, "What does IMF stand for?", ["International Monetary Fund", "International Money Federation", "Inter-Monetary Finance", "International Mercantile Fund"], 0, "IMF stands for International Monetary Fund. It is a UN-linked financial institution that supports global monetary cooperation.", "The IMF was established in 1944 at the Bretton Woods Conference and is headquartered in Washington DC.", [2900]),
(S, "Which country was the world's largest arms importer in the latest SIPRI data (2021-25)?", ["India", "Saudi Arabia", "Ukraine", "United States"], 2, "SIPRI's March 2026 data for 2021-25 ranks Ukraine first, with about 9.7 percent of global arms imports, followed by India. The USA is a major exporter, not the top importer.", "In the 2015-19 and earlier periods India or Saudi Arabia led, and India was second after Ukraine in 2020-24 data as well.", [4342, 4344, 4346]),
(S, "How many member countries does the Commonwealth of Nations have today?", ["52", "54", "56", "58"], 2, "The Commonwealth has 56 member states. Gabon and Togo joined on 29 June 2022, raising the total from 54 to 56.", "Older sources say 54 or 53 because they were written before 2022.", [1800]),
(S, "What is the approximate gestation (pregnancy) period of a buffalo?", ["About 150 days", "About 210 days", "About 310 days", "About 400 days"], 2, "A buffalo carries its calf for roughly 305 to 320 days, about 310 days. This is slightly longer than a cow.", "A cow's gestation period is about 283 days.", [3432]),
(S, "What is the approximate gestation (pregnancy) period of a cow?", ["About 283 days", "About 355 days", "About 150 days", "About 400 days"], 0, "A cow carries its calf for about 280 to 285 days, around nine months. 355 days is too long.", "A buffalo's gestation period is about 310 days.", [3433]),
(S, "On which date did India gain independence from British rule?", ["14 August 1947", "15 August 1947", "26 January 1950", "15 August 1948"], 1, "India became independent on 15 August 1947, one day after Pakistan. 26 January 1950 is India's Republic Day.", "Pakistan became independent on 14 August 1947.", [3056]),
(S, "Who was the first Prime Minister of India?", ["Jawaharlal Nehru", "Mahatma Gandhi", "Sardar Patel", "Lal Bahadur Shastri"], 0, "Jawaharlal Nehru became India's first Prime Minister on 15 August 1947 and served until 1964.", "Lal Bahadur Shastri was the second Prime Minister of India.", [5122]),
(S, "On which date did India's Constituent Assembly adopt the Constitution of India?", ["15 August 1947", "26 November 1949", "26 January 1950", "30 January 1948"], 1, "The Constituent Assembly adopted the Indian Constitution on 26 November 1949. It came into force on 26 January 1950.", "India celebrates 26 January as Republic Day.", [2574]),
(S, "On which river is the Bhakra Dam of India built?", ["Beas", "Ravi", "Sutlej", "Chenab"], 2, "The Bhakra Dam is built on the Sutlej River in Himachal Pradesh, India. It forms the Gobind Sagar reservoir.", "The Sutlej was allotted to India under the Indus Waters Treaty of 1960.", [2590]),
(S, "The Flemish people are a tribal or ethnic group inhabiting which country?", ["Netherlands", "Belgium", "Switzerland", "Luxembourg"], 1, "The Flemish are the Dutch-speaking people of Flanders in northern Belgium. The French-speaking people of southern Belgium are called Walloons.", "Brussels, the capital of Belgium, is also the seat of the European Union institutions.", [433]),
(S, "Which institution is responsible for distributing river water among the provinces of Pakistan?", ["WAPDA", "Indus River System Authority (IRSA)", "Federal Board of Revenue", "National Highway Authority"], 1, "IRSA was set up in 1992 under the Water Apportionment Accord of 1991 to distribute Indus system water among the provinces. WAPDA builds and runs dams and power projects.", "The Water Apportionment Accord was signed in 1991 by the four provinces.", [4393]),
(S, "What does integration (definite integral) of a function show geometrically?", ["Slope of the curve", "Area under the curve", "Length of the tangent", "Angle of the curve"], 1, "A definite integral gives the area between the curve and the x-axis over an interval. Slope is given by differentiation.", "Integration is the reverse process of differentiation.", [2901]),
(S, "At how many points can two distinct lines in a plane intersect each other?", ["At most one point", "Exactly two points", "Three points", "Infinitely many points"], 0, "Two distinct lines meet in at most one point. If they are parallel they do not meet at all.", "Two coincident lines share all their points, so they are not distinct.", [633, 1509]),
(S, "Where is the headquarters of the UN Office of the High Commissioner for Human Rights (UN Human Rights)?", ["New York", "Vienna", "Geneva", "Paris"], 2, "The OHCHR (UN Human Rights) is headquartered in Geneva, Switzerland. The UN Human Rights Council also meets in Geneva.", "The UN Headquarters itself is in New York.", [4180]),
(S, "What was the name of the father of Hazrat Ibrahim (AS) according to the Holy Quran?", ["Azar", "Tarikh", "Amran", "Lot"], 0, "Surah Al-An'am names Ibrahim's father as Azar. Some scholars say Tarikh (Terah) was his given name, so sources differ.", "Hazrat Ibrahim (AS) is called Khalilullah, the friend of Allah.", [3555]),
(S, "The Holy Prophet (PBUH) appointed Hazrat Muadh bin Jabal (RA) as governor of which region?", ["Yemen", "Syria", "Bahrain", "Egypt"], 0, "The Prophet (PBUH) sent Hazrat Muadh bin Jabal (RA) to Yemen as governor and teacher around 10 AH. He is known as an expert in halal and haram.", "Hazrat Muadh (RA) died in the plague of Amwas in Syria.", [1763]),
]
